def compute(vars):
    property_plant_equipment = vars["v1"]
    total_net_assets_acquired = vars["v2"]

    if total_net_assets_acquired == 0:
        return None

    ratio = property_plant_equipment / total_net_assets_acquired
    value = ratio * 100

    return {
        "value": value,
        "trace": {
            "property_plant_equipment": property_plant_equipment,
            "total_net_assets_acquired": total_net_assets_acquired,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
